#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<array<long long, 5>> p(n);
    for (auto& point : p)
        for (long long& coordinate : point)
            cin >> coordinate;

    if (n > 11) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> answer;

    for (int i = 0; i < n; ++i) {
        bool good = true;

        for (int j = 0; j < n && good; ++j) {
            if (j == i) continue;

            for (int k = j + 1; k < n; ++k) {
                if (k == i) continue;

                __int128 dot = 0;
                for (int d = 0; d < 5; ++d) {
                    dot += (__int128)(p[j][d] - p[i][d]) *
                           (p[k][d] - p[i][d]);
                }

                if (dot > 0) {
                    good = false;
                    break;
                }
            }
        }

        if (good)
            answer.push_back(i + 1);
    }

    cout << answer.size() << '\n';
    for (int index : answer)
        cout << index << '\n';

    return 0;
}

